def populate_tracking_codes(apps, schema_editor):
    Complaint = apps.get_model('missions', 'Complaint')
    alphabet = string.ascii_uppercase + string.digits
    used = set(Complaint.objects.exclude(tracking_code='').values_list('tracking_code', flat=True))
    for complaint in Complaint.objects.filter(tracking_code=''):
        for _ in range(50):
            code = ''.join(secrets.choice(alphabet) for _ in range(8))
            if code not in used:
                complaint.tracking_code = code
                complaint.save(update_fields=['tracking_code'])
                used.add(code)
                break


